-- English version of the boycott sheet summaries, shown when the app is in English.
-- The French summary stays the reference; a row without summary_en falls back to it.
alter table public.boycott_entities add column if not exists summary_en text;

update public.boycott_entities as e set summary_en = t.en
from (values
  ($t$3CE appartient au portefeuille L’Oréal Groupe. OUMMAH applique le statut rouge par héritage du groupe à partir d’un lien historique documenté par BDS ; la fiche ne prétend pas que cette marque finance directement l’armée israélienne.$t$, $t$3CE belongs to the L’Oréal Groupe portfolio. OUMMAH applies the red status through group inheritance, based on a historical link documented by BDS; this sheet does not claim that this brand directly funds the Israeli army.$t$),
  ($t$7UP fait partie du portefeuille PepsiCo. OUMMAH applique le statut rouge par héritage du groupe en raison de la propriété documentée de SodaStream par PepsiCo ; cela ne signifie pas que 7UP finance directement l’armée israélienne.$t$, $t$7UP is part of the PepsiCo portfolio. OUMMAH applies the red status through group inheritance because PepsiCo’s ownership of SodaStream is documented; this does not mean that 7UP directly funds the Israeli army.$t$),
